<script setup lang="ts">
import { computed, ref } from 'vue';
import { t } from '../../i18n';
import type { PdbReference } from '../../v2/workbench';
import ReviewHint from './ReviewHint.vue';
import ResearchProfile from './ResearchProfile.vue';
import ArticleEvidence from './ArticleEvidence.vue';
import { useFrozenPdfPool } from '../../approvals/frozenPdf';
import type { ArticleSourceContext } from './articleMetadata';
import { abstractStatusLabels, type ResearchProfile as ResearchProfileData } from './articleMetadata';
const props=defineProps<{sourceContext?:ArticleSourceContext;metadata:{abstract?:string|null;abstract_source?:string|null;pdb_references?:PdbReference[];pmid?:string|null;pmcid?:string|null;identifiers_source?:string|null;abstract_status?:keyof typeof abstractStatusLabels;abstract_note?:string|null;research_profile?:ResearchProfileData}}>();
useFrozenPdfPool();
const issue=computed(()=>props.metadata.abstract_status==='not_found'||props.metadata.abstract_status==='needs_review');
const expanded=ref(false);
const modules=[{key:'modalities',label:'分子类型'},{key:'mechanisms',label:'作用方式'},{key:'targets',label:'研究靶点与关联基因'},{key:'optimization_goals',label:'优化目标'},{key:'diseases',label:'疾病与应用方向'},{key:'pdb',label:'PDB'}] as const;
const usageLabels = {this_work:'本文结构',cited_structure:'引用结构',unknown:'用途待核对'};
</script>
<template><section class="article-metadata"><div v-if="metadata.pmid || metadata.pmcid" class="identifier-links"><a v-if="metadata.pmid" data-pmid-link :href="`https://pubmed.ncbi.nlm.nih.gov/${encodeURIComponent(metadata.pmid)}/`" target="_blank" rel="noopener">PMID: {{metadata.pmid}} ↗</a><a v-if="metadata.pmcid" :href="`https://pmc.ncbi.nlm.nih.gov/articles/${encodeURIComponent(metadata.pmcid)}/`" target="_blank" rel="noopener">PMCID: {{metadata.pmcid}} ↗</a></div>
<h3>Abstract</h3><div v-if="issue" class="abstract-issue"><p data-abstract-status>{{t(abstractStatusLabels[metadata.abstract_status!])}}</p><p v-if="metadata.abstract_note">{{metadata.abstract_note}}</p></div><p class="preserve-lines" :class="{'abstract-preview':!expanded && (metadata.abstract?.length??0)>1400}" data-article-abstract>{{ metadata.abstract || (metadata.abstract_status === 'not_found' ? '—' : t('尚未记录摘要')) }}</p><button v-if="(metadata.abstract?.length??0)>1400" type="button" class="button-quiet" :aria-expanded="expanded" @click="expanded=!expanded">{{t(expanded?'收起摘要':'展开完整摘要')}}</button>
<div class="article-module-grid"><section v-for="module in modules" :key="module.key" class="article-module" :class="{'compact-module':['modalities','mechanisms'].includes(module.key)}" :data-article-module="module.key"><h3>{{t(module.label)}} <span>{{module.key==='pdb'?metadata.pdb_references?.length??0:metadata.research_profile?.[module.key]?.length??0}}</span></h3><div class="module-body" tabindex="0" :aria-label="t(module.label)"><template v-if="module.key!=='pdb'"><ResearchProfile v-if="metadata.research_profile?.[module.key]?.length" :profile="{[module.key]:metadata.research_profile[module.key]}" :source-context="sourceContext" hide-headings /><p v-else class="empty-module">{{t('尚未记录')}}</p></template><template v-else><p v-if="!metadata.pdb_references?.length" class="empty-module">{{t('尚未记录 PDB ID；空白不表示文章一定未报告。')}}</p><ul v-else class="pdb-list"><li v-for="(entry,index) in metadata.pdb_references" :key="index"><a :href="`https://www.rcsb.org/structure/${encodeURIComponent(entry.pdb_id)}`" target="_blank" rel="noopener">{{entry.pdb_id}} ↗</a> · {{t(usageLabels[entry.usage])}}<span v-if="entry.compound_label"> · Compound {{entry.compound_label}}</span><ReviewHint :hint="entry.review_hint" /><details><summary>{{t('依据与说明')}}</summary><ArticleEvidence :evidence="entry.evidence" :source-context="sourceContext" /><p v-if="entry.source_page">p. {{entry.source_page}}</p><p v-if="entry.source_context">{{entry.source_context}}</p><p v-if="entry.review_hint">{{entry.review_hint}}</p></details></li></ul></template></div></section></div></section></template>
<style scoped>.identifier-links{display:flex;flex-wrap:wrap;gap:.5rem 1rem}.article-metadata{overflow-wrap:anywhere}.abstract-preview{display:-webkit-box;-webkit-line-clamp:8;-webkit-box-orient:vertical;overflow:hidden}.abstract-issue{border-left:3px solid var(--amber);padding-left:.7rem}.pdb-list{list-style:none;padding:0;display:grid;gap:.5rem}.pdb-list li{border:1px solid var(--line);border-radius:6px;padding:.7rem}details{margin-top:.5rem}summary{cursor:pointer;color:var(--ink-muted);font-size:.85rem}.article-module-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1rem;margin-top:1rem}.article-module{height:320px;min-width:0;border:1px solid var(--line);border-radius:8px;display:flex;flex-direction:column;overflow:hidden}.article-module.compact-module{height:220px}.article-module h3{margin:0;padding:.75rem 1rem;background:var(--surface);border-bottom:1px solid var(--line);font-size:.95rem;display:flex;justify-content:space-between;flex-shrink:0}.article-module h3 span{color:var(--ink-muted);font-size:.8rem}.module-body{overflow:auto;min-height:0;padding:.75rem;overscroll-behavior:contain;scrollbar-gutter:stable}.empty-module{font-size:.85rem;color:var(--ink-muted)}@media(max-width:760px){.article-module-grid{grid-template-columns:1fr}.article-module,.article-module.compact-module{height:auto;max-height:480px}.module-body{max-height:420px}} </style>
